-- Phase 4: Enterprise Payroll - Contributions, Allowances, and Approvals

-- 1. Add payroll contribution columns (idempotent via IF NOT EXISTS)
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS total_allowances NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS withholding_tax NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employer_sss NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employer_philhealth NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employer_pagibig NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employer_total_contributions NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employee_sss NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employee_philhealth NUMERIC(10,2) DEFAULT 0;
ALTER TABLE payroll ADD COLUMN IF NOT EXISTS employee_pagibig NUMERIC(10,2) DEFAULT 0;

-- 2. SSS Contribution Table
CREATE TABLE sss_contributions (
    id SERIAL PRIMARY KEY,
    salary_from NUMERIC(10,2) NOT NULL,
    salary_to NUMERIC(10,2) NOT NULL,
    employer_share NUMERIC(10,2) NOT NULL,
    employee_share NUMERIC(10,2) NOT NULL,
    total_contribution NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Seed 2024-2025 SSS Contribution Table (monthly) — idempotent via DO block
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM sss_contributions LIMIT 1) THEN
  END IF;
END $$;

-- 3. PhilHealth Contribution Table
CREATE TABLE philhealth_contributions (
    id SERIAL PRIMARY KEY,
    salary_from NUMERIC(10,2) NOT NULL,
    salary_to NUMERIC(10,2) NOT NULL,
    employee_rate NUMERIC(5,4) NOT NULL,
    employer_rate NUMERIC(5,4) NOT NULL,
    monthly_premium NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Seed 2024-2025 PhilHealth Premium Rate Table (4.5% rate, split 50/50)
SELECT 0, 10000, 0.0225, 0.0225, 450.00
WHERE NOT EXISTS (SELECT 1 FROM philhealth_contributions LIMIT 1);

SELECT 10000.01, 99999999.99, 0.0225, 0.0225, 2250.00
WHERE NOT EXISTS (SELECT 1 FROM philhealth_contributions WHERE salary_from = 10000.01);

-- 4. Pag-IBIG Contribution Table
CREATE TABLE pagibig_contributions (
    id SERIAL PRIMARY KEY,
    salary_from NUMERIC(10,2) NOT NULL,
    salary_to NUMERIC(10,2) NOT NULL,
    employee_share NUMERIC(10,2) NOT NULL,
    employer_share NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Seed 2024-2025 Pag-IBIG Contribution Table (monthly)
SELECT 0, 1500, 0.01, 0.02
WHERE NOT EXISTS (SELECT 1 FROM pagibig_contributions LIMIT 1);

SELECT 1500.01, 99999999.99, 0.02, 0.02
WHERE NOT EXISTS (SELECT 1 FROM pagibig_contributions WHERE salary_from = 1500.01);

-- 5. Withholding Tax (BIR TRAIN Law) Table
CREATE TABLE withholding_tax_brackets (
    id SERIAL PRIMARY KEY,
    salary_from NUMERIC(10,2) NOT NULL,
    salary_to NUMERIC(10,2) NOT NULL,
    tax_base NUMERIC(10,2) NOT NULL,
    percentage_over_base NUMERIC(5,4) NOT NULL,
    exempt_amount NUMERIC(10,2) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Seed BIR TRAIN Law Withholding Tax Table (monthly, effective 2023)
SELECT 0, 20833, 0, 0.0000, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets LIMIT 1);

SELECT 20833.01, 33333, 0, 0.1500, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets WHERE salary_from = 20833.01);

SELECT 33333.01, 66667, 1875, 0.2000, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets WHERE salary_from = 33333.01);

SELECT 66667.01, 166667, 8541.80, 0.2500, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets WHERE salary_from = 66667.01);

SELECT 166667.01, 666667, 33541.80, 0.3000, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets WHERE salary_from = 166667.01);

SELECT 666667.01, 999999999.99, 183541.80, 0.3500, 0
WHERE NOT EXISTS (SELECT 1 FROM withholding_tax_brackets WHERE salary_from = 666667.01);

-- 6. Allowance Tables
CREATE TABLE allowance_types (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    description TEXT,
    default_amount NUMERIC(10,2) DEFAULT 0,
    is_taxable BOOLEAN DEFAULT true,
    is_recurring BOOLEAN DEFAULT true,
    frequency VARCHAR(20) DEFAULT 'MONTHLY',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE employee_allowances (
    id SERIAL PRIMARY KEY,
    employee_id INTEGER NOT NULL REFERENCES employees(id) ON DELETE CASCADE,
    allowance_type_id INTEGER NOT NULL REFERENCES allowance_types(id) ON DELETE CASCADE,
    amount NUMERIC(10,2) NOT NULL DEFAULT 0,
    effective_date DATE,
    end_date DATE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- 7. Payroll Approvals Table
CREATE TABLE payroll_approvals (
    id SERIAL PRIMARY KEY,
    payroll_id INTEGER NOT NULL REFERENCES payroll(id) ON DELETE CASCADE,
    cutoff_start DATE,
    cutoff_end DATE,
    branch_id INTEGER REFERENCES branches(id) ON DELETE SET NULL,
    requested_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    requested_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    status VARCHAR(20) DEFAULT 'PENDING',
    reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,
    reviewed_at TIMESTAMP,
    remarks TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
